-- #79 follow-up: Broken Shore scenario heroes stand still (Pi team, Pro helper, 2026-09-29). Undo: undo_broken_shore_paths_79.sql
--
-- The Assault on Broken Shore scenario (map 1460, src/server/scripts/Scenario/BrokenIslands/broken_islands.cpp) moves
-- its hero NPCs with explicit me->GetMotionMaster()->MovePath(<id>, ...) calls. WaypointMovementGenerator::LoadPath
-- (src/server/game/Movement/MovementGenerators/WaypointMovementGenerator.cpp) reads an EXPLICIT path id (as opposed to
-- a creature's own creature_addon.path_id) through sWaypointMgr->GetPathScript(), which is loaded from
-- world.waypoint_data_script, not world.waypoint_data (WaypointManager.cpp). world.waypoint_data_script had no rows
-- for these ids, so the heroes never move: Genn Greymane (90717) at 439136/439137, Varian (90713) at
-- 439141/439144/439145/439146 on the Alliance side; Vol'jin (90708) and the Horde escort group
-- {90708,90709,90710,90711,90712,93704,97525} at 439148-439155.
--
-- Rows taken from a full world DB dump distributed with the same broken_islands.cpp this fix targets (verified: the
-- path ids referenced in that .cpp file are exactly the ids below, and every path's points form one continuous,
-- gapless sequence starting at point 1):
--   https://github.com/dufernst/LegionCore-7.3.5/blob/master/sql/base/LegionCore_world_2020_04_25.zip
--   (commit 429693ff79c128eccaaac807747632754fbb5534 at the time this was fetched; also present, same repo lineage,
--   in https://github.com/The-Legion-Preservation-Project/LegionCore-7.3.5)
--
-- Column mapping: the source dump's world.waypoint_data_script has columns
-- (id, point, position_x, position_y, position_z, orientation, delay, move_flag, speed, action, action_chance, entry,
-- wpguid) - 13 columns, no delay_chance (delay_chance only exists on world.waypoint_data, the other table). Chronicles
-- renamed move_flag -> move_type in both waypoint tables (sql/old/world/0034_waypoint_move_type.sql), so the only
-- change from the source rows is that column's name; values and order are otherwise used as-is.

DELETE FROM world.waypoint_data_script WHERE id IN
    (439136, 439137, 439141, 439144, 439145, 439146,
     439148, 439149, 439150, 439151, 439152, 439153, 439154, 439155);

